html:
{% set ui = json.loads(doc.ui_state) if doc.ui_state else {} %}
{% set form = ui.get('form') or {} %}
{% set calc = ui.get('calc_result') or {} %}
{% set sheet = calc.get('sheet') or {} %}
{% set pricing = calc.get('pricing') or {} %}
{% set cost_rows = calc.get('cost_rows') or [] %}
{% set gt = calc.get('group_totals') or {} %}
{% set is_flexo = (doc.pricing_type == 'Flexo') or (form.get('pricing_type') == 'Flexo') %}
{% set creator = frappe.db.get_value('User', doc.owner, 'full_name') or doc.owner %}
{% set modifier = frappe.db.get_value('User', doc.modified_by, 'full_name') or doc.modified_by %}
{% set ci_parent = frappe.db.get_value('Cost Item Calculation', {'calculation_breakdown': doc.name}, 'parent') %}
{% set breakdown_desc = frappe.db.get_value('cost Item', ci_parent, 'cost_item_name') if ci_parent else doc.name %}
{% set iqty = (pricing.get('item_qty') or doc.item_qty or 1) | float %}
{% set grand_v = gt.get('grand') or ((doc.unit_cost or 0) * iqty) %}
{% set sscl_pu = (pricing.get('sscl') or 0) / iqty %}
{% set vat_pu = (pricing.get('vat') or 0) / iqty %}
{% set sell_unit_v = pricing.get('sell_unit') or (doc.selling_price or 0) %}
{% set sell_total_v = pricing.get('sell_total') or (sell_unit_v * iqty) %}
{% set q_unit = (pricing.get('quoted_cost') or 0) / iqty %}
{% set prod_label = 'Over Head Costs' if is_flexo else 'Production Costs' %}
<style>
body{margin:0;padding:0}
.wrap{font-family:Arial,sans-serif;font-size:9.5pt;color:#000;padding:4mm 6mm}
.top-right{text-align:right;font-size:8pt;color:#444;margin-bottom:6px}
.hd{display:flex;align-items:center;gap:10px;margin-bottom:4px}
.co{font-size:12pt;font-weight:bold}
.co-sub{font-size:9pt;color:#333}
.title{text-align:center;font-size:13pt;font-weight:bold;letter-spacing:.05em;margin:6px 0 12px;border-bottom:2px solid #1a3a5c;padding-bottom:4px}
.meta{width:100%;border-collapse:collapse;margin-bottom:10px}
.meta td{padding:2px 0;font-size:9.5pt}
.meta .lb{font-weight:bold;width:170px}
.ct{width:100%;border-collapse:collapse;margin-bottom:10px;font-size:9pt}
.ct th{background:#1a3a5c;color:#fff;padding:5px 8px;text-align:left;border:1px solid #999}
.ct th.r{text-align:right}
.ct td{padding:3px 8px;border-bottom:1px solid #ebebeb}
.ct td.r{text-align:right;font-family:monospace}
.ct .gh td{background:#2e6da0;color:#fff;font-weight:bold;padding:4px 8px}
.ct .gh td.r{text-align:right;font-family:monospace}
.bot{width:100%;border-collapse:collapse;margin-top:4px}
.bot td{vertical-align:top;padding:0}
.sp{width:100%;border-collapse:collapse}
.sp td{padding:2px 4px;font-size:9pt;border-bottom:1px solid #f0f0f0}
.sp td.k{color:#333;width:52%}
.sp td.v{font-weight:600;width:48%}
.pt{width:100%;border-collapse:collapse}
.pt td{padding:2px 6px;font-size:9pt;border-bottom:1px solid #f0f0f0}
.pt td.k{color:#333;width:58%}
.pt td.v{text-align:right;font-family:monospace;font-weight:600;width:42%}
.pt .tot td{background:#1a3a5c;color:#fff;font-weight:bold}
.remarks{margin-top:10px;font-size:9pt}
.mat-tbl{width:100%;border-collapse:collapse;margin-top:10px;font-size:9pt}
.mat-tbl th{background:#1a3a5c;color:#fff;padding:4px 8px;text-align:left;border:1px solid #999}
.mat-tbl td{padding:4px 8px;border:1px solid #ddd}
@media print{.wrap{padding:0}}
</style>
<div class='wrap'>

<div class='top-right'>
  Created at {{ (doc.creation | string)[:10] if doc.creation else '' }} by {{ creator }}<br>
  Updated at {{ (doc.modified | string)[:10] if doc.modified else '' }} by {{ modifier }}
</div>

<div class='hd'>
  <div>
    <div class='co'>Savinda Graphic Systems (Pvt) Ltd.</div>
    <div class='co-sub'>Printing &amp; Packaging</div>
  </div>
</div>

<div class='title'>Product Costing Summary</div>

<table class='meta'>
  <tr><td class='lb'>Sales Inquiry</td><td>: {{ doc.ref or '' }}</td></tr>
  <tr><td class='lb'>Customer</td><td>: {{ doc.customer_name or '' }}</td></tr>
  <tr><td class='lb'>Inquiry Breakdown</td><td>: {{ breakdown_desc or doc.name }}</td></tr>
  <tr><td class='lb'>Breakdown Quantity</td><td>: {{ '{:,}'.format(doc.item_qty | int) }}</td></tr>
</table>

<table class='ct'>
  <thead>
    <tr>
      <th style='width:42%'>DESCRIPTION</th>
      <th class='r' style='width:16%'>ESTIMATED QTY.</th>
      <th class='r' style='width:18%'>UNIT PRICE(LKR)</th>
      <th class='r' style='width:24%'>AMOUNT(LKR)</th>
    </tr>
  </thead>
  <tbody>
    {% for g, g_label in [('Material', 'Material Costs'), ('Preparation', 'Preparation Costs'), ('Production', prod_label)] %}
      {% set ns = namespace(total=0.0, count=0) %}
      {% for row in cost_rows %}
        {% if row.get('cost_group', '') == g %}
          {% set ns.total = ns.total + (row.get('amount') or 0) %}
          {% set ns.count = ns.count + 1 %}
        {% endif %}
      {% endfor %}
      {% if ns.count > 0 %}
        <tr class='gh'>
          <td colspan='3'>{{ g_label }}</td>
          <td class='r'>{{ '{:,.2f}'.format(ns.total) }}</td>
        </tr>
        {% for row in cost_rows %}
          {% if row.get('cost_group', '') == g %}
            {% if row.get('is_auto') %}
              {% set desc = row.get('selected_item_name') or row.get('selected_item') or row.get('cost_fact', '') %}
            {% elif row.get('selected_item_name') and row.get('selected_item_name') != row.get('selected_item') %}
              {% set desc = row.get('cost_fact', '') + ' : ' + row.get('selected_item_name', '') %}
            {% else %}
              {% set desc = row.get('cost_fact', '') %}
            {% endif %}
            <tr>
              <td>{{ desc }}</td>
              <td class='r'>{{ '{:.6g}'.format(row.get('req_qty') or 0) }}</td>
              <td class='r'>{{ '{:.8g}'.format(row.get('rate') or 0) }}</td>
              <td class='r'>{{ '{:,.2f}'.format(row.get('amount') or 0) }}</td>
            </tr>
          {% endif %}
        {% endfor %}
      {% endif %}
    {% endfor %}
  </tbody>
</table>

<table class='bot'>
  <tr>
    <td style='width:46%;padding-right:12px'>
      <table class='sp'>
        {% if not is_flexo %}
        <tr><td class='k'>Ctn Size</td><td class='v'>: {{ form.get('carton_size') or '-' }}</td></tr>
        <tr><td class='k'>F.Sheet Size</td><td class='v'>: {{ form.get('full_sheet_l', 0) }} x {{ form.get('full_sheet_w', 0) }} INCH</td></tr>
        <tr><td class='k'>C.Sheet Size</td><td class='v'>: {{ form.get('cut_sheet_l', 0) }} x {{ form.get('cut_sheet_w') or form.get('cut_sheetw', 0) }} INCH</td></tr>
        <tr><td class='k'>Ups</td><td class='v'>: {{ form.get('no_of_ups', 0) }}</td></tr>
        <tr><td class='k'>Cuts</td><td class='v'>: {{ form.get('no_of_cuts', 0) }}</td></tr>
        <tr><td class='k'>Colors</td><td class='v'>: {{ form.get('no_of_colors', 0) }}</td></tr>
        {% else %}
        <tr><td class='k'>Sticker Size (L * W)</td><td class='v'>: {{ form.get('product_length_mm', 0) }} X {{ form.get('product_width_mm', 0) }}</td></tr>
        <tr><td class='k'>Ups</td><td class='v'>: {{ sheet.get('ups', '-') }}</td></tr>
        <tr><td class='k'>Colors</td><td class='v'>: {{ form.get('no_of_colors', 0) }}</td></tr>
        <tr><td class='k'>Stickers per Reel</td><td class='v'>: {{ '{:,}'.format((sheet.get('stickers_per_reel') or 0) | int) }}</td></tr>
        <tr><td class='k'>Material Width</td><td class='v'>: {{ form.get('reel_width_mm', 0) }}</td></tr>
        {% endif %}
      </table>
    </td>
    <td style='width:54%'>
      <table class='pt'>
        <tr><td class='k'>Order Quantity</td><td class='v'>{{ '{:,}'.format(doc.item_qty | int) }}</td></tr>
        {% if not is_flexo %}
        <tr><td class='k'>Total Value</td><td class='v'>{{ '{:,.2f}'.format(grand_v) }}</td></tr>
        <tr><td class='k'>Unit Cost</td><td class='v'>{{ '{:,.2f}'.format(pricing.get('unit_cost') or doc.unit_cost or 0) }}</td></tr>
        <tr><td class='k'>SSCL 2.5 %</td><td class='v'>{{ '{:,.2f}'.format(sscl_pu) if sscl_pu else '0' }}</td></tr>
        <tr><td class='k'>Proft Margin</td><td class='v'>{{ form.get('profit_margin', 0) | int }} %</td></tr>
        <tr><td class='k'>Quoted Price</td><td class='v'>{{ '{:,.2f}'.format(q_unit) }}</td></tr>
        <tr><td class='k'>VAT 18%</td><td class='v'>{{ '{:,.2f}'.format(vat_pu) if vat_pu else '0' }}</td></tr>
        <tr class='tot'><td class='k'>Final Value</td><td class='v'>{{ '{:,.2f}'.format(sell_unit_v) }}</td></tr>
        <tr><td class='k'>Material Contribution</td><td class='v'>{{ '{:,.2f}'.format(pricing.get('mat_contrib') or 0) }}</td></tr>
        {% else %}
        <tr><td class='k'>Total Value</td><td class='v'>{{ '{:,.2f}'.format(grand_v) }}</td></tr>
        <tr><td class='k'>SSCL 2.5 %</td><td class='v'>{{ '{:,.2f}'.format(sscl_pu) if sscl_pu else '0' }}</td></tr>
        <tr><td class='k'>Proft Margin</td><td class='v'>{{ form.get('profit_margin', 0) | int }} %</td></tr>
        <tr><td class='k'>Selling Price</td><td class='v'>{{ '{:,.2f}'.format(sell_total_v) }}</td></tr>
        <tr><td class='k'>Unit Cost</td><td class='v'>{{ '{:,.2f}'.format(pricing.get('unit_cost') or doc.unit_cost or 0) }}</td></tr>
        <tr><td class='k'>Quoted Price</td><td class='v'>{{ '{:,.2f}'.format(q_unit) }}</td></tr>
        <tr><td class='k'>VAT 18%</td><td class='v'>{{ '{:,.2f}'.format(vat_pu) if vat_pu else '0' }}</td></tr>
        <tr class='tot'><td class='k'>Final Value</td><td class='v'>{{ '{:,.2f}'.format(sell_unit_v) }}</td></tr>
        <tr><td class='k'>Material Contribution</td><td class='v'>{{ '{:,.2f}'.format(pricing.get('mat_contrib') or 0) }}</td></tr>
        {% endif %}
      </table>
    </td>
  </tr>
</table>

{% if doc.remarks %}
<div class='remarks'><b>Remarks :</b><br>{{ doc.remarks | replace('\n', '<br>') }}</div>
{% endif %}

<div style='margin-top:10px;font-size:9pt;font-weight:bold'>Materials :</div>
<table class='mat-tbl'>
  <thead>
    <tr>
      <th style='width:35%'>Material</th>
      <th style='width:12%'>Type</th>
      <th style='width:13%'>Quantity</th>
      <th style='width:13%'>Tolerance</th>
      <th style='width:13%'>Reissue</th>
      <th style='width:14%'>Unit</th>
    </tr>
  </thead>
  <tbody>
    <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr>
  </tbody>
</table>

</div>

{% set sp_name = frappe.db.get_value('User', doc.sales_person, 'full_name') or doc.sales_person or '' %}
{% set sp_desig = frappe.db.get_value('User', doc.sales_person, 'designation') or '' %}
{% set ns_i = namespace(names=[]) %}
{% for row in doc.items %}{% if row.item_name and row.item_name not in ns_i.names %}{% set ns_i.names = ns_i.names + [row.item_name] %}{% endif %}{% endfor %}
<style>
body{margin:0;padding:0}
.wrap{font-family:Arial,sans-serif;font-size:10pt;color:#000;padding:6mm 8mm}
.hdr-tbl{width:100%;border-collapse:collapse;margin-bottom:4px}
.hdr-tbl td{vertical-align:middle;padding:2px}
.logo-td{width:120px;text-align:center;vertical-align:middle}
.logo-td img{max-height:65px}
.co-td{text-align:center}
.co-name{font-size:11pt;font-weight:bold;margin-bottom:2px}
.co-info{font-size:8.5pt;font-style:italic;line-height:1.6}
.q-title{text-align:center;font-size:15pt;font-weight:bold;letter-spacing:.08em;margin:8px 0 4px}
.meta-tbl{width:100%;border-collapse:collapse;margin-bottom:8px}
.meta-right{text-align:right;font-size:9pt;line-height:1.7;vertical-align:top}
.to-blk{font-weight:bold;font-size:10pt;margin:6px 0 4px}
.intro{font-size:9.5pt;margin-bottom:8px}
.items-tbl{width:100%;border-collapse:collapse;margin-bottom:8px;font-size:9.5pt}
.items-tbl thead tr{border-top:1.5px solid #000;border-bottom:1.5px solid #000}
.items-tbl th{padding:5px 6px;font-weight:bold;font-size:9pt;border:none}
.th-lbl{width:33%;text-align:left}
.th-qty{width:36%;text-align:center}
.th-pr{width:31%;text-align:center}
.item-hdr td{padding:10px 6px 3px;font-size:10pt}
.lbl-td{padding:2px 6px;vertical-align:top;width:33%}
.val-td{padding:2px 6px;vertical-align:top}
.price-row td{padding:2px 6px}
.qty-td{text-align:center;width:36%}
.pr-td{text-align:right;width:31%}
.rmk-sep td{padding:6px 6px 2px;font-size:9.5pt}
.rmk-hdr{font-size:9.5pt;margin:10px 0 2px}
.footer-hr{border:0;border-top:1px solid #000;margin:8px 0}
.bullets{font-size:9.5pt;margin-bottom:8px}
.bullets p{margin:3px 0}
.ch-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-bottom:10px}
.ch-tbl td{padding:2px 0;vertical-align:top}
.ch-lbl{width:220px}
.closing{font-size:9.5pt;margin:10px 0 14px}
.sign{font-size:9.5pt;line-height:1.9}
@media print{.wrap{padding:2mm}}
</style>
<div class='wrap'>

<table class='hdr-tbl'><tr>
  <td class='logo-td'><img src='/files/Savinda-Logo.png'></td>
  <td class='co-td'>
    <div class='co-name'>Savinda Graphic Systems (Pvt) Ltd.</div>
    <div class='co-info'>
      NO: 145, UDA Industrial Estate, Katuwana Road, Homagama, Sri Lanka.<br>
      Tel: +94 11 4368 571 Hot Line: +94 11 4651 755 Fax: +94 11 4303 253<br>
      Email: info@savinda.lk Web: www.savinda.lk
    </div>
  </td>
</tr></table>

<div class='q-title'>QUOTATION</div>

<table class='meta-tbl'><tr>
  <td></td>
  <td class='meta-right'>
    Quote Number: {{ doc.name }}<br>
    Inquiry Number: {{ doc.inquiry or '' }}<br>
    Date: {{ doc.date | string if doc.date else '' }}
  </td>
</tr></table>

<div class='to-blk'>TO : {{ doc.customer_name or '' }}</div>
<div class='intro'>In response to your inquiry, we are pleased to submit the following quotation:</div>

<table class='items-tbl'>
  <thead><tr>
    <th class='th-lbl'></th>
    <th class='th-qty'>Quantity (Pcs)/Reel/Sheet/M/SQM/Set</th>
    <th class='th-pr'>Price Per Piece (LKR)</th>
  </tr></thead>
  <tbody>
    {% for iname in ns_i.names %}
      <tr class='item-hdr'><td colspan='3'><u><b>Item Name - {{ iname }}</b></u></td></tr>
      {% set ns_v = namespace(vks=[]) %}
      {% for row in doc.items %}{% if row.item_name == iname %}{% set vk = (row.finishing_variant or 0) | string %}{% if vk not in ns_v.vks %}{% set ns_v.vks = ns_v.vks + [vk] %}{% endif %}{% endif %}{% endfor %}
      {% for vi in range(ns_v.vks | length) %}
        {% set vk = ns_v.vks[vi] %}
        {% if vi > 0 %}<tr class='rmk-sep'><td colspan='3'>Remark</td></tr>{% endif %}

        {# Collect first-row fields + CB name for this variant #}
        {% set ns_r = namespace(got=False, sz='', mat='', fin='', cb='') %}
        {% for row in doc.items %}{% if row.item_name == iname and (row.finishing_variant or 0) | string == vk and not ns_r.got %}{% set ns_r.got = True %}{% set ns_r.sz = row.size or '' %}{% set ns_r.mat = row.material or '' %}{% set ns_r.fin = row.finishing or '' %}{% set ns_r.cb = row.calculation_breakdown or '' %}{% endif %}{% endfor %}

        {# Auto-fill missing fields from linked Calculation Breakdown #}
        {% if ns_r.cb %}
          {% set cb_ui_raw = frappe.db.get_value('Calculation Breakdown', ns_r.cb, 'ui_state') or '{}' %}
          {% set cb_ui = json.loads(cb_ui_raw) %}
          {% set cb_form = cb_ui.get('form') or {} %}
          {% set is_flexo = cb_form.get('pricing_type') == 'Flexo' %}

          {# Material: fetch Item name from CB base_material #}
          {% if not ns_r.mat %}
            {% set bmat_code = frappe.db.get_value('Calculation Breakdown', ns_r.cb, 'base_material') or '' %}
            {% if bmat_code %}
              {% set ns_r.mat = frappe.db.get_value('Item', bmat_code, 'item_name') or bmat_code %}
            {% endif %}
          {% endif %}

          {# Size: construct from CB dimensions #}
          {% if not ns_r.sz %}
            {% if is_flexo %}
              {% set pl = cb_form.get('product_length_mm') or 0 %}
              {% set pw = cb_form.get('product_width_mm') or 0 %}
              {% if pl and pw %}{% set ns_r.sz = (pl | int | string) + ' mm x ' + (pw | int | string) + ' mm' %}{% endif %}
            {% else %}
              {% set cl = cb_form.get('cut_sheet_l') or frappe.db.get_value('Calculation Breakdown', ns_r.cb, 'cut_sheet_l') or 0 %}
              {% set cw = cb_form.get('cut_sheet_w') or cb_form.get('cut_sheetw') or frappe.db.get_value('Calculation Breakdown', ns_r.cb, 'cut_sheetw') or 0 %}
              {% if cl and cw %}{% set ns_r.sz = (cl | int | string) + ' x ' + (cw | int | string) + ' INCH' %}{% endif %}
            {% endif %}
          {% endif %}

          {# Finishing: XX Colors + spec1 + spec2 from CB ui_state #}
          {% if not ns_r.fin %}
            {% set n_colors = cb_form.get('no_of_colors') or frappe.db.get_value('Calculation Breakdown', ns_r.cb, 'no_of_colors') or 0 %}
            {% set cb_specs = cb_ui.get('selected_specs') or [] %}
            {% set ns_sp = namespace(parts=[]) %}
            {% for sp in cb_specs %}{% if sp.get('spec_name') %}{% set ns_sp.parts = ns_sp.parts + [sp.get('spec_name')] %}{% endif %}{% endfor %}
            {% set c_str = '{:02d} Colors'.format(n_colors | int) if n_colors else '' %}
            {% if ns_sp.parts %}
              {% set ns_r.fin = c_str + (' + ' if c_str else '') + (ns_sp.parts | join(' + ')) %}
            {% else %}
              {% set ns_r.fin = c_str %}
            {% endif %}
          {% endif %}
        {% endif %}

        {# Render Size / Material / Finishing rows #}
        {% if ns_r.sz %}<tr><td class='lbl-td'>Size</td><td colspan='2' class='val-td'>: {{ ns_r.sz }}</td></tr>{% endif %}
        {% if ns_r.mat %}<tr><td class='lbl-td'>Material</td><td colspan='2' class='val-td'>: {{ ns_r.mat }}</td></tr>{% endif %}
        {% if ns_r.fin %}<tr><td class='lbl-td'>Finishing</td><td colspan='2' class='val-td'>: {{ ns_r.fin }}</td></tr>{% endif %}

        {# Qty / Price rows #}
        {% for row in doc.items %}{% if row.item_name == iname and (row.finishing_variant or 0) | string == vk %}<tr class='price-row'><td></td><td class='qty-td'>{{ '{:.0f}'.format(row.qty or 0) }}</td><td class='pr-td'>{{ '{:.2f}'.format(row.selling_price or 0) }}</td></tr>{% endif %}{% endfor %}
      {% endfor %}
    {% endfor %}
  </tbody>
</table>

<div class='rmk-hdr'>Remark</div>
{% if doc.remarks %}<div style='font-size:9.5pt;margin-bottom:4px'>{{ doc.remarks }}</div>{% endif %}

<hr class='footer-hr'>

<div class='bullets'>
  <p>* Please note that the above prices are valid only for {{ doc.validity_note or '07 Days/01 month/02 month/03 month' }}</p>
  <p><b>* Prices are based on {{ doc.duty_basis or 'Duty Free Basis./Duty Paid Basis' }}</b></p>
  <p>* {% if doc.vat_note %}{{ doc.vat_note }}{% else %}Prices do not include VAT/Inclusive of Vat{% endif %}</p>
</div>

<table class='ch-tbl'>
  <tr>
    <td class='ch-lbl'>Plate  Charges</td>
    <td>: {% if doc.plate_charges %}{{ '{:,.0f}'.format(doc.plate_charges) }} LKR{% endif %}{% if doc.plate_per_colour %} Per Colour{% endif %}</td>
  </tr>
  <tr>
    <td class='ch-lbl'>Die cutter Charges/Block Charges</td>
    <td>: {% if doc.die_cutter_charges %}{{ '{:,.0f}'.format(doc.die_cutter_charges) }}{% endif %}</td>
  </tr>
  <tr>
    <td class='ch-lbl'>Payment Terms</td>
    <td>: {{ doc.payment_terms or '' }}</td>
  </tr>
</table>

<p class='closing'>We trust our pricing is competitive and look forward to your favorable response.Please feel free to contact us for any further Clarification.</p>

<div class='sign'>
  Thank you,<br>
  Your faithfully,<br><br>
  {{ sp_name }}{% if sp_desig %}<br>{{ sp_desig }}{% endif %}
</div>

</div>
